const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const item = $input.first().json;
const hdrs = item.headers || {};
const body = item.body && typeof item.body === 'object' ? item.body : item;

function stableStringify(v) {
  if (v === null || v === undefined) return 'null';
  const t = typeof v;
  if (t === 'number' || t === 'boolean') return JSON.stringify(v);
  if (t === 'string') return JSON.stringify(v);
  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
  if (t === 'object') {
    const keys = Object.keys(v).sort();
    return '{' + keys.map((k) => JSON.stringify(k) + ':' + stableStringify(v[k])).join(',') + '}';
  }
  return JSON.stringify(String(v));
}

const secret = String($env.CASTUO_AUDIT_WEBHOOK_SECRET || '').trim();
if (secret) {
  const signingPayload = stableStringify(body);
  const expected = crypto.createHmac('sha256', secret).update(signingPayload, 'utf8').digest('hex');
  const rawSig = String(hdrs['x-castuo-signature'] || hdrs['X-Castuo-Signature'] || '').trim();
  const normalized = rawSig.replace(/^sha256=/i, '').trim();
  if (!normalized || normalized.toLowerCase() !== expected) {
    return [{ json: { ok: false, audit_error: true, error: 'INVALID_SIGNATURE' } }];
  }
}

const kindRaw = String(body.kind || body.entry_kind || 'sistema').toLowerCase();
const isIA =
  kindRaw === 'ia' ||
  kindRaw === 'analitico' ||
  kindRaw === 'analítico';

const out = body.output && typeof body.output === 'object' ? body.output : {};
const agenteId =
  body.agente_id != null
    ? String(body.agente_id)
    : body.agente != null
      ? String(body.agente)
      : 'agente-desconocido';
const decision =
  body.decision != null
    ? String(body.decision)
    : out.decision != null
      ? String(out.decision)
      : '(sin decisión)';
const confianza =
  body.confianza != null ? Number(body.confianza) : out.confianza != null ? Number(out.confianza) : null;
const confStr = Number.isFinite(confianza) ? String(confianza) : 'n/d';

const event = body.event != null ? String(body.event) : 'Acción rutinaria';
const actor = body.actor != null ? String(body.actor) : 'Sistema automático';
const status = body.status != null ? String(body.status) : 'OK';
const details =
  body.details != null ? JSON.stringify(body.details, null, 2) : '(sin detalles)';

const now = new Date();
const isoShort = now.toISOString();
const ymd = now.toISOString().slice(0, 10);

let ctx = '';
if (body.contexto != null) ctx = String(body.contexto);
else if (body.details != null) ctx = JSON.stringify(body.details, null, 2);
else ctx = '';
if (ctx.length > 8000) ctx = ctx.slice(0, 8000) + '\n...(truncado)';
if (!ctx) ctx = '(sin contexto adicional)';

let block;
if (isIA) {
  const iaParts = [
    '',
    '### [' + isoShort + '] IA · **' + agenteId + '** #ia-decision',
    '- **Confianza (0-100):** ' + confStr,
    '- **Decisión:** ' + decision
  ];
  if (Array.isArray(body.tags) && body.tags.length > 0) {
    iaParts.push('- **Etiquetas:** ' + body.tags.map(function (x) { return String(x); }).join(' '));
  }
  iaParts.push('- **Contexto / datos:**', ctx, '');
  block = iaParts.join('\n');
} else {
  block = [
    '',
    '### [' + isoShort + '] Sistema · **' + actor + '** #evento-sistema',
    '- **Evento:** ' + event,
    '- **Estado:** ' + status,
    '- **Detalles:**',
    details,
    ''
  ].join('\n');
}

const baseDir = path.join('/data/cerebros-auditoria', 'journal');
const filePath = path.join(baseDir, 'diario-' + ymd + '.md');

const dayHeader =
  '---\n' +
  'tags: [diario, operacion, castuo-agri-brain]\n' +
  'fecha: "' +
  ymd +
  '"\n' +
  'estado_general: "ok"\n' +
  '---\n' +
  '# Diario de operación: ' +
  ymd +
  '\n\n' +
  '## Decisiones de IA (cerebro analítico)\n' +
  '_Antes de actuaciones físicas, el análisis queda registrado aquí._\n\n' +
  '## Eventos del sistema (cerebro operativo)\n' +
  '_Telemetría, webhooks y estado operativo._\n\n';

try {
  fs.mkdirSync(baseDir, { recursive: true });
  if (!fs.existsSync(filePath)) {
    fs.writeFileSync(filePath, dayHeader, 'utf8');
  }
  fs.appendFileSync(filePath, block, 'utf8');
} catch (e) {
  return [
    {
      json: {
        ok: false,
        audit_error: true,
        error: 'FILE_WRITE_FAILED',
        message: String(e.message)
      }
    }
  ];
}

return [{ json: { ok: true, filePath, ymd, kind: isIA ? 'ia' : 'sistema' } }];
